import inspect

JSON_TYPES = {int: "integer", str: "string", float: "number", bool: "boolean"}


def tool_from(fn, name=None, description=None):
    signature = inspect.signature(fn)
    parameters = {}
    required = []
    for parameter_name, parameter in signature.parameters.items():
        annotation = parameter.annotation
        parameters[parameter_name] = JSON_TYPES.get(annotation, "string")
        if parameter.default is inspect.Parameter.empty:
            required.append(parameter_name)
    if description is None:
        doc = inspect.getdoc(fn) or ""
        description = doc.splitlines()[0].strip() if doc else ""
    return {
        "name": name or fn.__name__,
        "description": description,
        "parameters": parameters,
        "required": required,
        "call": fn,
    }


def query_engine_tool(engine, name, description):
    def query(query: str) -> str:
        return engine(query)

    tool = tool_from(query, name=name, description=description)
    return tool


def catalog(tools):
    return [{"name": tool["name"], "description": tool["description"],
             "parameters": tool["parameters"], "required": tool["required"]}
            for tool in tools.values()]


def run_agent(planner, tools, max_steps=6):
    state = {}
    trace = []
    for step in range(1, max_steps + 1):
        decision = planner(state, catalog(tools))
        if "final" in decision:
            return {"answer": decision["final"], "steps": step, "trace": trace}
        name = decision.get("tool")
        args = dict(decision.get("args") or {})
        tool = tools.get(name)
        if tool is None:
            known = ", ".join(sorted(tools))
            observation = f"Error: unknown tool {name!r}. Available: {known}"
        else:
            missing = [p for p in tool["required"] if p not in args]
            unexpected = [a for a in args if a not in tool["parameters"]]
            if missing:
                observation = (f"Error: {name} is missing required argument(s): "
                               f"{', '.join(missing)}")
            elif unexpected:
                observation = (f"Error: {name} got unexpected argument(s): "
                               f"{', '.join(unexpected)}")
            else:
                try:
                    observation = tool["call"](**args)
                except Exception as exc:
                    observation = f"Error: {exc}"
        trace.append({"tool": name, "args": args, "observation": observation})
        state[decision.get("save_as", f"step{step}")] = observation
    return {"answer": None, "steps": max_steps, "trace": trace}
